      "interpretation": "Recuperação desde o fundo de junho; negociando próximo à MM50 e banda superior."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$37.0",
      "interpretation": "Curto prazo em leve viés de alta; preço acima da MM20 (suporte imediato)."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$38.8",
      "interpretation": "Médio prazo relativamente plano/levemente descendente; resistência imediata próxima."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$37.4",
      "interpretation": "Longo prazo com inclinação levemente positiva; preço acima indica viés estrutural neutro/positivo."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$37.5",
      "interpretation": "EMA curta cruzou/está acima da EMA21 — sinal de reversão/momentum de curto prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$37.0",
      "interpretation": "Confirma suporte dinâmico de curto-médio prazo; posição abaixo da EMA9 no fechamento recente."
    },
    {
      "indicator": "MACD",
      "reading": "MACD ligeiramente positivo; histograma verde pequeno",
      "interpretation": "Momentum comprador retornando; cruzamento acima da linha de sinal sugere continuidade de alta de curto prazo."
    },
    {
      "indicator": "Bandas de Bollinger (20,2)",
      "reading": "Bandas relativamente estreitas; preço próximo da banda superior",
      "interpretation": "Baixa volatilidade recente; possível expansão caso movimento comprador ganhe volume — caso contrário risco de recuo."
    },
    {
      "indicator": "RSI14",
      "reading": "≈ 60",
      "interpretation": "Força relativa em zona neutra/positiva; não indica sobrecompra."
    },
    {
      "indicator": "Volume",
      "reading": "Moderado (abaixo dos picos de março/maio)",
      "interpretation": "Recuperação sem confirmação volumétrica forte; limita convicção do rompimento imediato."
    }
  ]
}
